SELECT "customerid", "taxid", "status", "lastname", "firstname", "middleinitial", "gender", "tier", "dob", "addressline1", "addressline2", "postalcode", "city", "stateprov", "country", "phone1", "phone2", "phone3", "email1", "email2", "nationaltaxratedesc", "nationaltaxrate", "localtaxratedesc", "localtaxrate", "agencyid", "creditrating", "networth", "marketingnameplate", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY customerid, effectivedate) AS int) AS "sk_customerid" FROM (SELECT TRY_CAST((CAST(c.C_ID AS INTEGER)) AS int) AS "customerid", TRY_CAST((CAST(COALESCE(c.C_TAX_ID, '') AS CHAR(20))) AS char(20)) AS "taxid", TRY_CAST((act.ActionType) AS char(10)) AS "status", TRY_CAST((CAST(COALESCE(n.C_L_NAME, '') AS CHAR(30))) AS char(30)) AS "lastname", TRY_CAST((CAST(n.C_F_NAME AS CHAR(30))) AS char(30)) AS "firstname", TRY_CAST((CAST(n.C_M_NAME AS CHAR(1))) AS char(1)) AS "middleinitial", TRY_CAST((c.C_GNDR) AS char(1)) AS "gender", TRY_CAST((TRY_CAST(c.C_TIER AS INTEGER)) AS int) AS "tier", TRY_CAST((COALESCE(c.C_DOB, CAST('1900-01-01' AS DATE))) AS date) AS "dob", TRY_CAST((CAST(COALESCE(a.C_ADLINE1, '') AS VARCHAR(80))) AS varchar(80)) AS "addressline1", TRY_CAST((CAST(a.C_ADLINE2 AS VARCHAR(80))) AS varchar(80)) AS "addressline2", TRY_CAST((CAST(COALESCE(a.C_ZIPCODE, '') AS CHAR(12))) AS char(12)) AS "postalcode", TRY_CAST((CAST(COALESCE(a.C_CITY, '') AS CHAR(25))) AS char(25)) AS "city", TRY_CAST((CAST(COALESCE(a.C_STATE_PROV, '') AS CHAR(20))) AS char(20)) AS "stateprov", TRY_CAST((a.C_CTRY) AS char(24)) AS "country", TRY_CAST((CAST(SUBSTRING(p1.C_CTRY_CODE || p1.C_AREA_CODE || p1.C_LOCAL || p1.C_EXT, 1, 30) AS CHAR(30))) AS char(30)) AS "phone1", TRY_CAST((LEFT(CONCAT(p2.C_CTRY_CODE, p2.C_AREA_CODE, p2.C_LOCAL, p2.C_EXT), 30)) AS char(30)) AS "phone2", TRY_CAST((LEFT(CASE WHEN p3.C_LOCAL IS NOT NULL THEN CONCAT(CASE WHEN p3.C_CTRY_CODE IS NOT NULL THEN p3.C_CTRY_CODE || '-' END, CASE WHEN p3.C_AREA_CODE IS NOT NULL THEN p3.C_AREA_CODE || '-' END, p3.C_LOCAL, CASE WHEN p3.C_EXT IS NOT NULL THEN ' ext ' || p3.C_EXT END) END, 30)) AS char(30)) AS "phone3", TRY_CAST((CAST(ci.C_PRIM_EMAIL AS CHAR(50))) AS char(50)) AS "email1", TRY_CAST((CAST(ci.C_ALT_EMAIL AS VARCHAR(50))) AS char(50)) AS "email2", TRY_CAST((tr_nat.TX_NAME) AS varchar(50)) AS "nationaltaxratedesc", TRY_CAST((tr_nat.TX_RATE) AS decimal(6, 5)) AS "nationaltaxrate", TRY_CAST((tr_loc.TX_NAME) AS varchar(50)) AS "localtaxratedesc", TRY_CAST((tr_loc.TX_RATE) AS decimal(6, 5)) AS "localtaxrate", TRY_CAST((CAST(NULL AS CHAR(30))) AS char(30)) AS "agencyid", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "creditrating", TRY_CAST((CAST(NULL AS DECIMAL(10))) AS decimal(10)) AS "networth", TRY_CAST((CAST(NULL AS VARCHAR(100))) AS varchar(100)) AS "marketingnameplate", TRY_CAST((COALESCE(act.ActionType = 'NEW', FALSE)) AS boolean) AS "iscurrent", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "batchid", TRY_CAST((CAST(TRY_CAST(REPLACE(REPLACE(act.ActionTS, 'T', ' '), 't', ' ') AS TIMESTAMP) AS DATE)) AS date) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS date) AS "enddate" FROM CustomerXML AS c
LEFT JOIN NameXML AS n ON c.Customer_Id = n.Customer_Id
LEFT JOIN AddressXML AS a ON c.Customer_Id = a.Customer_Id
LEFT JOIN ContactInfoXML AS ci ON c.Customer_Id = ci.Customer_Id
LEFT JOIN C_PHONE_1_XML AS p1 ON ci.ContactInfo_Id = p1.ContactInfo_Id
LEFT JOIN C_PHONE_2_XML AS p2 ON ci.ContactInfo_Id = p2.ContactInfo_Id
LEFT JOIN C_PHONE_3_XML AS p3 ON ci.ContactInfo_Id = p3.ContactInfo_Id
LEFT JOIN TaxInfoXML AS t ON c.Customer_Id = t.Customer_Id
LEFT JOIN TaxRate AS tr_nat ON t.C_NAT_TX_ID = tr_nat.TX_ID
LEFT JOIN TaxRate AS tr_loc ON t.C_LCL_TX_ID = tr_loc.TX_ID
LEFT JOIN ActionXML AS act ON c.Action_Id = act.Action_Id)
